import React from 'react';
import './about.css';

function About() {
  return (
    <div className="about-container">
      <h2 align="center">About Us</h2>
      <p>
        Welcome to our calorie calculator and meal suggestion website! 
      </p>
      <p>
        We're passionate about helping you make healthier choices and achieve your fitness goals.
      </p>
      <p>
        Our team of nutrition experts and developers has curated a comprehensive database of foods and recipes to provide accurate calorie information. 
      </p>
      <p>
        Whether you're tracking your daily intake or planning balanced meals, we've got you covered.
      </p>
      <p>
        Feel free to explore our features, calculate your daily caloric needs, and discover delicious recipes tailored to your dietary preferences.
      </p>
    </div>
  );
}

export default About;
